  password = "securepassword123"
  db_name = "primarydb"
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.main.id]
  subnet_group_name = aws_db_subnet_group.main.name
}

resource "aws_db_instance" "replica_2" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "5.7"
  username = "admin"
  password = "securepassword123"
  db_name = "primarydb"
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.main.id]
  subnet_group_name = aws_db_subnet_group.main.name
}

resource "aws_security_group" "main" {
  name = "main-sg"
  description = "Main security group"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "main" {
  name = "main-subnet-group"
  description = "Main database subnet group"

  subnet_ids = [aws_subnet.main.id]
}

resource "aws_subnet" "main" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.main.id
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.example.com"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.primary.endpoint]
}

resource "aws_route53_record" "replica_1_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.example.com"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.replica_1.endpoint]
  weighted_routing_policy {
    weight = 1
  }
}

resource "aws_route53_record" "replica_2_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.example.com"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.replica_2.endpoint]
  weighted_routing_policy {
    weight = 1
  }
}
