  backup_retention_period = 7
  backup_window = "03:00-04:00"
  enable_performance_insights = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id = aws_kms_key.my_db_kms_key.arn
  tags = {
    Name = "my_db_instance"
  }
}

