        Action   = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "${aws_s3_bucket.web_app_bucket.arn}",
          "${aws_s3_bucket.web_app_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Create a CloudFront distribution to deliver content from the S3 bucket
resource "aws_cloudfront_distribution" "web_app_distribution" {
  enabled = true

  aliases = ["www.mywebapp.com"]

  default_root_object = "index.html"

  origin {
    domain_name = aws_s3_bucket.web_app_bucket.bucket_domain_name
    origin_id   = "S3Origin"
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "allow-all"
  }

  logging_config {
    bucket = aws_s3_bucket.web_app_bucket.bucket
    include_cookies = false
    prefix = "cloudfront-logs/"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    ssl_support_method = "sni-only"
    acm_certificate_arn = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"
  }
}

# Create a Route 53 record to map a domain name to the CloudFront distribution
resource "aws_route53_record" "web_app_record" {
  zone_id = "Z1234567890ABCDEF"
  name    = "www.mywebapp.com"
  type    = "A"

  alias {
    evaluate_target_health = true
    name                  = aws_cloudfront_distribution.web_app_distribution.domain_name
    zone_id               = aws_cloudfront_distribution.web_app_distribution.hosted_zone_id
  }
}

# Create an IAM role for Elastic Beanstalk
resource "aws_iam_role" "beanstalk_service" {
  name = "beanstalk-service-role-${random_string.random_suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "Beanstalk Service Role"
    Environment = "Production"
  }
}

# Create an IAM policy attachment for the Elastic Beanstalk service role
resource "aws_iam_policy_attachment" "beanstalk_service_policy" {
  name       = "beanstalk-service-policy-${random_string.random_suffix.result}"
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBeanstalkServiceRolePolicy"
  roles      = [aws_iam_role.beanstalk_service.name]
}

# Create an Elastic Beanstalk application
resource "aws_elastic_beanstalk_application" "web_app" {
  name        = "my-web-app"
  description = "My Web Application"

  appversion_lifecycle {
    service_role          = aws_iam_role.beanstalk_service.arn
    max_count             = 128
    delete_source_from_s3 = true
  }
}

# Create an Elastic Beanstalk environment
resource "aws_elastic_beanstalk_environment" "web_app_env" {
  name                = "my-web-app-env"
  application         = aws_elastic_beanstalk_application.web_app.name
  solution_stack_name = "64bit Amazon Linux 2015.03 v2.0.3 running Go 1.4"
  environment_id      = "my-web-app-env-id-${random_string.random_suffix.result}"
  tags = {
    Name        = "My Web App Environment"
    Environment = "Production"
  }
}

# Create an Elastic Beanstalk configuration template
resource "aws_elastic_beanstalk_configuration_template" "web_app_config" {
  name                = "my-web-app-config"
  application         = aws_elastic_beanstalk_application.web_app.name
  solution_stack_name = "64bit Amazon Linux 2015.03 v2.0.3 running Go 1.4"

  setting {
    name        = "aws:InstanceType"
    namespace   = "aws:autoscaling:asg"
    value       = "t3.micro"
    resource    = "AutoScalingGroup"
  }

  setting {
    name        = "aws:EC2KeyName"
    namespace   = "aws:autoscaling:asg"
    value       = "my-key-pair"
    resource    = "AutoScalingGroup"
  }
}

# Create an Elastic Beanstalk application version
resource "aws_elastic_beanstalk_application_version" "web_app_version" {
  name        = "my-web-app-version-1"
  application = aws_elastic_beanstalk_application.web_app.name
  bucket      = aws_s3_bucket.web_app_bucket.bucket
  key         = "my-web-app-version-1.zip"
  description = "My Web Application Version 1"

  tags = {
    Name        = "My Web App Version 1"
    Environment = "Production"
  }
}

# Create an Auto Scaling group
resource "aws_autoscaling_group" "web_app_asg" {
  availability_zones = ["us-west-2a", "us-west-2b"]
  max_size           = 3
  min_size           = 1

  launch_configuration = aws_launch_configuration.web_app_lc.name

  tags = {
    Name        = "My Web App ASG"
    Environment = "Production"
  }
}

# Create a Launch Configuration
resource "aws_launch_configuration" "web_app_lc" {
  name_prefix   = "my-web-app-lc"
  image_id      = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"

  security_groups = ["sg-0123456789abcdef0"]

  user_data = <<-EOF
#!/bin/bash
yum update -y
yum install -y nginx
nginx -g 'daemon off;'
EOF
}
