          "kinesisanalytics:GetApplicationSnapshot",
          "kinesisanalytics:ListApplicationSnapshots",
          "kinesisanalytics:RestoreFromSnapshot",
          "kinesisanalytics:StartApplicationSnapshot",
          "kinesisanalytics:StopApplicationSnapshot",
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach IAM policy to IAM role
resource "aws_iam_role_policy_attachment" "kinesis_analytics_role_policy_attachment" {
  policy_arn = aws_iam_policy.kinesis_analytics_policy.arn
  role       = aws_iam_role.kinesis_analytics_role.name
}

# Default Kinesis Stream for input
resource "aws_kinesis_stream" "kinesis_stream" {
  name        = "kinesis-stream-input"
  retention_period = 24
}

# Default Kinesis Input for Flink Application
resource "aws_kinesisv2_input" "flink_input" {
  name        = "flink-input"
  stream_arn = aws_kinesis_stream.kinesis_stream.arn
}

# Default Kinesis Output for Flink Application
resource "aws_kinesisv2_output" "flink_output" {
  name        = "flink-output"
  stream_arn = aws_kinesis_stream.kinesis_stream.arn
}

# Default Input Mapping for Flink Application
resource "aws_kinesisv2_application_input_mapping" "flink_input_mapping" {
  application_name = aws_kinesisv2_analytics_application.flink_analytics_app.name
  input_id         = aws_kinesisv2_input.flink_input.id
  input_schema {
    record_format {
      record_format_type = "JSON"
      json_ser_de {
        record_keys = ["KEY"]
        record_values {
          json_path = "$.value"
        }
      }
    }
    record_column {
      name     = "KEY"
      mapping = "$.key"
    }
    record_column {
      name     = "VALUE"
      mapping = "$.value"
    }
  }
}

# Default Output Mapping for Flink Application
resource "aws_kinesisv2_application_output_mapping" "flink_output_mapping" {
  application_name = aws_kinesisv2_analytics_application.flink_analytics_app.name
  output_id         = aws_kinesisv2_output.flink_output.id
  kinesis_firehose_output {
    firehose_arn = aws_kinesis_firehose_delivery_stream.flink_output_stream.arn
  }
}

# Default Kinesis V2 Analytics Application
resource "aws_kinesisv2_analytics_application" "flink_analytics_app" {
  name                   = "flink-analytics-app"
  runtime_environment    = "FLINK-1_8"
  service_execution_role = aws_iam_role.kinesis_analytics_role.arn

  application_configuration {
    application_code_configuration {
      code_content {
        s3_content_location {
          bucket_arn = aws_s3_bucket.flink_app_bucket.arn
          file_key   = "flink-app.jar"
        }
      }

      code_content_type = "ZIPFILE"
    }

    environment_properties {
      property_group {
        property_group_id = "PROPERTY-GROUP-1"

        property_map = {
          "Key1" = "Value1"
        }
      }

      property_group {
        property_group_id = "PROPERTY-GROUP-2"

        property_map = {
          "KeyA" = "ValueA"
          "KeyB" = "ValueB"
        }
      }
    }

    flink_application_configuration {
      checkpoint_configuration {
        configuration_type = "DEFAULT"
      }

      monitoring_configuration {
        configuration_type = "CUSTOM"
        log_level          = "DEBUG"
        metrics_level      = "TASK"
      }

      parallelism_configuration {
        auto_scaling_enabled = true
        configuration_type   = "CUSTOM"
        parallelism          = 10
        parallelism_per_kpu  = 4
      }
    }
  }

  tags = {
    Environment = "test"
  }
}

# Default S3 Bucket for Flink Application
resource "aws_s3_bucket" "flink_app_bucket" {
  bucket = "example-flink-application"
  acl    = "private"
}

# Default Kinesis Firehose Delivery Stream for Output
resource "aws_kinesis_firehose_delivery_stream" "flink_output_stream" {
  name        = "flink-output-stream"
  destination = "s3"

  s3_destination_configuration {
    bucket_arn = aws_s3_bucket.flink_app_bucket.arn
    role_arn   = aws_iam_role.kinesis_analytics_role.arn
  }
}
