provider "aws" {
  region = "us-west-2"  # Replace with your desired AWS region
}

# Create an IAM role for Firehose to assume
resource "aws_iam_role" "firehose_role" {
  name = "firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Create an S3 bucket for Firehose to store data
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "firehose-bucket-${var.environment}"

  tags = {
    Name        = "Firehose Bucket"
    Environment = var.environment
  }
}

# Create an OpenSearch Serverless collection
resource "aws_opensearchserverless_collection" "osserverless_collection" {
  name = "firehose-osserverless-collection-${var.environment}"

  depends_on = [aws_iam_role.firehose_role]

  timeouts {
    create = "10m"
    delete = "10m"
  }
}

# Configure the OpenSearch Serverless collection's security policy
resource "aws_opensearchserverless_security_policy" "osserverless_security_policy" {
  name = "firehose-osserverless-security-policy-${var.environment}"
  type = "encryption"

  policy = jsonencode({
    Rules = [
      {
        Resource = ["collection/${aws_opensearchserverless_collection.osserverless_collection.name}"]
        ResourceType = "collection"
      }
    ],
    AWSOwnedKey = true
  })
}

# Create a Kinesis Firehose delivery stream with OpenSearch Serverless as the destination
resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-delivery-stream-${var.environment}"
  destination = "opensearchserverless"

  opensearchserverless_configuration {
    collection_endpoint = aws_opensearchserverless_collection.osserverless_collection.collection_endpoint
    role_arn            = aws_iam_role.firehose_role.arn
    index_name          = "firehose-index-${var.environment}"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_role.arn
      bucket_arn         = aws_s3_bucket.firehose_bucket.arn
      buffering_size     = 10
      buffering_interval = 400
      compression_format = "GZIP"
    }

    processing_configuration {
      enabled = true

      processors {
        type = "Lambda"
        parameters {
          parameter_name  = "LambdaArn"
          parameter_value = "arn:aws:lambda:us-west-2:123456789012:function:firehose-lambda:${var.environment}:$LATEST"
        }
      }
    }
  }
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  default     = "dev"
}
