provider "aws" {
  region = "us-east-1"
}

# Create a VPC with two subnets and a security group
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_1" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_security_group" "main" {
  vpc_id = aws_vpc.main.id
  description = "Main security group"
  ingress {
    from_port = 22
    to_port = 22
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an Elasticsearch domain with VPC settings
resource "aws_elasticsearch_domain" "main" {
  domain_name = "tf-example-es"

  cluster_config {
    instance_count         = 2
    zone_awareness_enabled = true
    instance_type          = "t2.small.elasticsearch"
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  vpc_options {
    subnet_ids         = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
    security_group_ids = [aws_security_group.main.id]
  }
}

# Create an IAM role for Firehose to access Elasticsearch
resource "aws_iam_role" "firehose_es_role" {
  name = "firehose_es_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Attach an inline policy to the Firehose role
resource "aws_iam_role_policy" "firehose_es_policy" {
  name   = "firehose_es_policy"
  role   = aws_iam_role.firehose_es_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomains",
          "es:DescribeElasticsearchDomainConfig",
        ]
        Resource = [
          aws_elasticsearch_domain.main.arn,
          "${aws_elasticsearch_domain.main.arn}/*",
        ]
      },
    ]
  })
}

# Create an S3 bucket for Firehose to store backups
resource "aws_s3_bucket" "firehose_backup_bucket" {
  bucket = "tf-example-firehose-backup"
  acl    = "private"
}

# Create an IAM role for Firehose to access S3
resource "aws_iam_role" "firehose_s3_role" {
  name = "firehose_s3_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Attach an inline policy to the S3 role
resource "aws_iam_role_policy" "firehose_s3_policy" {
  name   = "firehose_s3_policy"
  role   = aws_iam_role.firehose_s3_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.firehose_backup_bucket.arn,
          "${aws_s3_bucket.firehose_backup_bucket.arn}/*",
        ]
      },
    ]
  })
}

# Create a Kinesis Firehose delivery stream with Elasticsearch destination
resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = "tf-example-firehose"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn = aws_elasticsearch_domain.main.arn
    role_arn   = aws_iam_role.firehose_es_role.arn
    index_name = "tf-example-index"
    type_name  = "tf-example-type"

    s3_configuration {
      role_arn   = aws_iam_role.firehose_s3_role.arn
      bucket_arn = aws_s3_bucket.firehose_backup_bucket.arn
    }

    vpc_config {
      subnet_ids         = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
      security_group_ids = [aws_security_group.main.id]
      role_arn           = aws_iam_role.firehose_es_role.arn
    }
  }
}
