provider "aws" {
  region = "us-east-1"  # Change to your desired region
}

# Create an S3 bucket with versioning, server-side encryption, and public access restrictions
resource "aws_s3_bucket" "terraform_state_bucket" {
  bucket = "terraform-state-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  block_public_access {
    block_public_acls       = true
    ignore_public_acls     = true
    restrict_public_buckets = true
    block_public_policy    = true
  }
}

# Create a DynamoDB table for Terraform locking
resource "aws_dynamodb_table" "terraform_lock_table" {
  name           = "terraform-lock-table-${var.environment}"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
}
