resource "aws_security_group" "allow_ssh" {
  name        = "allow_ssh"
  description = "Allow SSH inbound traffic"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_ec2_fleet" "ec2_fleet" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.linux_2_launch_template.id
      version            = aws_launch_template.linux_2_launch_template.latest_version
    }
  }

  target_capacity_specification {
    default_target_capacity_type = "spot"
    total_target_capacity        = 9
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
    max_total_price     = "0.05"
  }

  spot_options {
    allocation_strategy = "lowest-price"
    max_total_price     = "0.05"
  }
}
