  region = "us-west-2"
}

resource "aws_sns_topic" "example_topic" {
  name = "example-topic"
}

resource "aws_cloudwatch_metric_alarm" "example_metric_alarm" {
  alarm_name                = "example-metric-alarm"
  comparison_operator       = "GreaterThanThreshold"
  evaluation_periods        = 2
  metric_name               = "CPUUtilization"
  namespace                 = "AWS/EC2"
  period                    = 120
  statistic                 = "Average"
  threshold                 = 80
  alarm_description         = "This metric monitors EC2 CPU utilization"
  insufficient_data_actions = []

  metric_query {
    id     = "example-query"
    expression = "SUM(SEARCH('AWS/EC2', 'CPUUtilization'))"
    label   = "Total CPU Utilization"
    period  = 300
    return_data = true
  }
}

resource "aws_cloudwatch_composite_alarm" "example_composite_alarm" {
  alarm_name        = "example-composite-alarm"
  alarm_rule        = <<EOF
ALARM(${aws_cloudwatch_metric_alarm.example_metric_alarm.alarm_name})
EOF

  alarm_actions = [aws_sns_topic.example_topic.arn]
  ok_actions    = [aws_sns_topic.example_topic.arn]

  actions_suppressor {
    alarm            = "suppressor-alarm"
    extension_period = 10
    wait_period      = 20
  }
}
