provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for SageMaker to assume
resource "aws_iam_role" "sagemaker_assume_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for SageMaker to access S3 and KMS
resource "aws_iam_policy" "sagemaker_policy" {
  name = "sagemaker_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "kms:Decrypt",
          "kms:Encrypt"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.sagemaker_bucket.arn}",
          "${aws_s3_bucket.sagemaker_bucket.arn}/*",
          "${aws_kms_key.sagemaker_kms_key.arn}"
        ]
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "sagemaker_policy_attachment" {
  role       = aws_iam_role.sagemaker_assume_role.name
  policy_arn = aws_iam_policy.sagemaker_policy.arn
}

# Create an S3 bucket for model data
resource "aws_s3_bucket" "sagemaker_bucket" {
  bucket = "sagemaker-bucket-${random_string.random_suffix.result}"

  tags = {
    Name = "SageMaker Bucket"
  }
}

# Create a KMS key for encrypting model data
resource "aws_kms_key" "sagemaker_kms_key" {
  description = "KMS key for SageMaker model data"

  tags = {
    Name = "SageMaker KMS Key"
  }
}

# Create a SageMaker model using the KMeans image
resource "aws_sagemaker_model" "kmeans_model" {
  name               = "kmeans-model"
  execution_role_arn = aws_iam_role.sagemaker_assume_role.arn

  container {
    image = "763104351884.dkr.ecr.us-west-2.amazonaws.com/sagemaker-kmeans:latest"
  }
}
```

