  bucket = aws_s3_bucket.pipeline_definition_bucket.bucket
  key    = "pipeline-definition.json"
  source = "path/to/your/pipeline-definition.json"

  depends_on = [aws_iam_role.sagemaker_execution_role]
}

resource "aws_sagemaker_pipeline" "example_pipeline" {
