}

resource "aws_iam_role" "dynamodb_encryption_role" {
  name = "dynamodb_encryption_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

