          }
          Action = [
            "kms:Encrypt",
            "kms:Decrypt",
            "kms:GenerateDataKey",
            "kms:GenerateDataKeyWithoutPlaintext"
          ]
          Resource = aws_kms_key.dynamodb_encryption_key.arn
        }
      ]
    })
  }
