}

# Default values for variables
variable "neptune_cluster_identifier_prefix" {
  default = "neptune-cluster-"
}

variable "neptune_instance_identifier_prefix" {
  default = "neptune-instance-"
}

variable "neptune_subnet_group_name" {
  default = "neptune-subnet-group"
}

variable "neptune_parameter_group_family" {
  default = "neptune1"
}

# Create Neptune subnet group
resource "aws_neptune_subnet_group" "default" {
  name       = var.neptune_subnet_group_name
  subnet_ids = ["subnet-12345678", "subnet-23456789"]  # Replace with actual subnet IDs
  description = "Managed by Terraform"
}

# Create Neptune parameter group
