  family      = var.neptune_parameter_group_family
  name        = "${var.neptune_cluster_identifier_prefix}-cluster-param-group"
  description = "Custom parameter group for Neptune cluster"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
