provider "aws" {
  region = "us-west-2"
}

# Create a Neptune subnet group
resource "aws_neptune_subnet_group" "example" {
  name       = "neptune-subnet-group"
  subnet_ids = [aws_subnet.example.id]

  description = "Subnet group for Neptune cluster"
}

# Create a Neptune cluster parameter group
resource "aws_neptune_cluster_parameter_group" "neptune_cluster_param_group" {
  family      = "neptune1"
  name        = "neptune-cluster-param-group"
  description = "Parameter group for Neptune cluster"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }
}

# Create a Neptune instance parameter group
resource "aws_neptune_parameter_group" "neptune_instance_param_group" {
  family      = "neptune1"
  name        = "neptune-instance-param-group"
  description = "Parameter group for Neptune instance"

  parameter {
    name  = "neptune_query_timeout"
    value = "25"
  }
}

# Create a Neptune cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster-example"
  engine                              = "neptune"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
  skip_final_snapshot                 = true
  iam_database_authentication_enabled = true
  apply_immediately                   = true

  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.neptune_cluster_param_group.name
  neptune_instance_parameter_group_name = aws_neptune_instance_param_group.neptune_instance_param_group.name
  neptune_subnet_group_name           = aws_neptune_subnet_group.example.name
}

# Create a Neptune instance
resource "aws_neptune_instance" "neptune_instance" {
  cluster_identifier = aws_neptune_cluster.neptune_cluster.id
  instance_class     = "db.r4.large"
  apply_immediately  = true

  neptune_subnet_group_name = aws_neptune_subnet_group.example.name
  neptune_parameter_group_name = aws_neptune_instance_param_group.neptune_instance_param_group.name
}

# Create a security group
resource "aws_security_group" "neptune_sg" {
  name        = "neptune-sg"
  description = "Security group for Neptune instance"

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a subnet
resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create a route table
resource "aws_route_table" "neptune_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

# Create a route table association
resource "aws_route_table_association" "neptune_rt_assoc" {
  route_table_id = aws_route_table.neptune_rt.id
  subnet_id      = aws_subnet.example.id
}

# Create an internet gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}
