provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "redshift_events" {
  name = "redshift-events"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "redshift-cluster-1"
  node_type          = "dc1.large"
  master_username    = "admin"
  master_password    = "Password123!"
  cluster_parameter_group_name = "default.redshift-1.0"

  logging {
    enable = true
    bucket_name = "redshift-events-bucket"
    log_destination_type = "cloudwatch_logs"
    log_exports = ["slowquery", "error"]
    s3_key_prefix = "logs/"
  }

  snapshot_copy {
    destination_region = "us-east-1"
    retention_period = 7
  }

  tags = {
    Name = "Redshift Cluster"
  }
}

resource "aws_redshift_event_subscription" "redshift_event_subscription" {
  name          = "redshift-event-subscription"
