```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# Create an S3 bucket for storing results
resource "aws_s3_bucket" "results_bucket" {
  bucket = "codebuild-results-bucket-${var.project_name}"

  tags = {
    Name = "CodeBuild Results Bucket"
  }
}

# Create an S3 bucket policy to allow CodeBuild to write to the bucket
resource "aws_s3_bucket_policy" "results_bucket_policy" {
  bucket = aws_s3_bucket.results_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = ["arn:aws:s3:::${aws_s3_bucket.results_bucket.bucket}/*"]
      },
    ]
  })
}

# Create a CodeBuild project
resource "aws_codebuild_project" "autograder_project" {
  name          = var.project_name
  description   = "Autograder for CS class"
  service_role  = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.results_bucket.bucket
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "SOME_KEY1"
      value = "SOME_VALUE1"
    }

    environment_variable {
      name  = "SOME_KEY2"
      value = "SOME_VALUE2"
      type  = "PARAMETER_STORE"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "codebuild-logs-${var.project_name}"
      stream_name = "autograder"
    }

    s3_logs {
      status   = "ENABLED"
      location = "${aws_s3_bucket.results_bucket.id}/build-log"
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/your-repo-url.git"
    git_clone_depth = 1

    git_submodules_config {
      fetch_submodules = true
    }
  }

  source_version = "master"

  vpc_config {
    vpc_id = aws_vpc.default.id
    subnets = [aws_subnet.default.id]
    security_group_ids = [aws_security_group.default.id]
  }

  tags = {
    Environment = "Development"
  }
}

# Create a VPC
resource "aws_vpc" "default" {
  cidr_block       = "10.0.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name = "Default VPC"
  }
}

# Create a subnet
resource "aws_subnet" "default" {
  vpc_id     = aws_vpc.default.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "Default Subnet"
  }
}

# Create a security group
resource "aws_security_group" "default" {
  name        = "default"
  description = "Default security group"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Default Security Group"
  }
}

variable "project_name" {
  description = "Name of the CodeBuild project"
  default     = "cs-class-autograder"
}
