  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_codebuild_project" "autograder_project" {
  name = "cs-class-autograder"
  service_role = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type = "LOCAL"
    modes = ["LOCAL_DOCKER_LAYER_CACHE", "LOCAL_SOURCE_CACHE"]
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "GITHUB_TOKEN"
      value = var.github_token
    }

    environment_variable {
      name  = "GITHUB_REPO"
      value = var.github_repo
    }

    environment_variable {
      name  = "GITHUB_BRANCH"
      value = var.github_branch
    }

    environment_variable {
      name  = "RESULT_BUCKET"
      value = var.result_bucket
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "cs-class-autograder-logs"
      stream_name = "autograder-${aws_codebuild_project.autograder_project.name}"
    }

    s3_logs {
      status   = "ENABLED"
      location = "${aws_s3_bucket.result_bucket_for_autograder.bucket}/build-log"
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/cs-class-autograder.git"
    git_clone_depth = 1
  }

  source_version = "main"

  vpc_config {
    vpc_id = aws_vpc.vpc_for_autograder.id
    subnets = [aws_subnet.subnet_for_autograder.id]
    security_group_ids = [aws_security_group.security_group_for_autograder.id]
  }

  tags = {
    Environment = "Development"
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "cs-class-autograder-codebuild-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_s3_bucket" "result_bucket_for_autograder" {
  bucket = "cs-class-autograder-results"
  acl = "private"
}

resource "aws_s3_bucket_policy" "s3_bucket_policy_for_autograder" {
  bucket = aws_s3_bucket.result_bucket_for_autograder.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = ["arn:aws:s3:::${aws_s3_bucket.result_bucket_for_autograder.bucket}/*"]
      },
    ]
  })
}

variable "github_token" {
  description = "GitHub personal access token for autograder"
  default = "your-github-personal-access-token"
}

variable "github_repo" {
  description = "GitHub repository for autograder"
  default = "example/cs-class-autograder"
}

variable "github_branch" {
  description = "GitHub branch for autograder"
  default = "main"
}

variable "result_bucket" {
  description = "S3 bucket for storing autograder results"
  default = "cs-class-autograder-results"
}
