provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the necessary policies to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Create a Lambda function to run the code
resource "aws_lambda_function" "code_runner" {
  function_name = "daily_code_run"
  role           = aws_iam_role.lambda_execution_role.arn
  handler        = "index.handler"
  runtime        = "python3.8"
  timeout        = 30

  # Define the Lambda function code
  code {
    s3_bucket = "my-lambda-bucket"
    s3_key    = "daily_code.py"
  }

  # Define the environment variables
  environment {
    variables = {
      RUN_TIME = "7:00 UTC"
    }
  }
}

# Create an EventBridge rule to trigger the Lambda function daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_code_run" {
  name        = "daily_code_run"
  description = "Runs the daily code at 7 UTC"
  schedule_expression = "cron(0 7 * * ? *)"
  depends_on = [aws_lambda_function.code_runner]
}
```

