```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# Create a Lambda function
resource "aws_lambda_function" "lambda_func" {
  function_name = "my-cron-lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  code {
    s3_bucket = "my-lambda-bucket"
    s3_key    = "lambda_func.zip"
  }

  environment {
    variables = {
      CRON_EXPRESSION = "cron(0 7 * * ? *)"
    }
  }
}

# Create an S3 bucket to store the Lambda deployment package
resource "aws_s3_bucket" "lambda_bucket" {
  bucket = "my-lambda-bucket"
  acl    = "private"
}

# Create an IAM policy to allow EventBridge to invoke the Lambda function
resource "aws_lambda_permission" "lambda_permission" {
  statement_id  = "AllowEventBridgeInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lambda_func.function_name
  principal     = "events.amazonaws.com"
}

# Create an EventBridge rule to trigger the Lambda function
resource "aws_cloudwatch_event_rule" "cron" {
  name        = "cron-rule"
  description = "EventBridge rule for daily cron job"
  schedule_expression = "cron(0 7 * * ? *)"
  target {
    arn       = aws_lambda_function.lambda_func.arn
    target_id = "LambdaTarget"
  }
}
