provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "dolphinscheduler_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "dolphinscheduler_public_subnet_1" {
  vpc_id            = aws_vpc.dolphinscheduler_vpc.id
  cidr_block        = cidrsubnet(aws_vpc.dolphinscheduler_vpc.cidr_block, 8, 1)
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "dolphinscheduler_public_subnet_2" {
  vpc_id            = aws_vpc.dolphinscheduler_vpc.id
  cidr_block        = cidrsubnet(aws_vpc.dolphinscheduler_vpc.cidr_block, 8, 2)
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "dolphinscheduler_db_sg" {
  name        = "dolphinscheduler_db_sg"
  description = "Security group for database access"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "dolphinscheduler_postgres_db" {
  ami           = "ami-0c55b159cbfafe1f0"  # Replace with a valid AMI for PostgreSQL 17.1
  instance_type = "t3.micro"
  key_name       = "my-key-pair"          # Replace with your existing key pair name
  vpc_security_group_ids = [aws_security_group.dolphinscheduler_db_sg.id]
  subnet_id         = aws_subnet.dolphinscheduler_public_subnet_1.id
  tags = {
    Name = "dolphinscheduler-postgres-db"
  }

  lifecycle {
    create_before_destroy = true
  }

  provisioner "local-exec" {
    command = "echo 'CREATE DATABASE dolphinscheduler;' | psql -U postgres -h ${aws_instance.dolphinscheduler_postgres_db.public_ip} -d postgres"
  }
}
