provider "aws" {
  region = "us-west-2"
}

resource "aws_rds_option_group" "option_group_pike" {
  name        = "option-group-pike"
  major_engine_version = "11"
  engine_name = "sqlserver-ee"

  option {
    name = "SQLSERVER_AUDIT"
    options {
      name = "IAM_ROLE_ARN"
      value = "arn:aws:iam::123456789012:role/SQLSERVER_AUDIT_ROLE"
    }
    options {
      name = "S3_BUCKET_ARN"
      value = "s3://pike-audit-bucket"
    }
  }

  option {
    name = "TDE"
  }
}

resource "aws_iam_role" "iam_role_pike" {
  name = "SQLSERVER_AUDIT_ROLE"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "iam_policy_pike" {
  name = "SQLSERVER_AUDIT_POLICY"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Resource = "arn:aws:s3:::pike-audit-bucket/*"
      },
    ]
  })
}

resource "aws_s3_bucket" "s3_bucket_pike" {
  bucket = "pike-audit-bucket"
  acl = "private"
}
