  engine_family = "aurora-mysql"
  name          = "my-db-proxy"
  role_arn       = aws_iam_role.proxy.arn
  vpc_subnet_ids = [aws_subnet.primary.id, aws_subnet.secondary.id]
  require_tls    = true

