provider "aws" {
  region = "us-west-2"
}

resource "aws_lightsail_instance" "lightsail_instance" {
  name              = "lightsail-instance"
  availability_zone = "us-west-2a"
  blueprint_id      = "ubuntu_20_04"
  bundle_id         = "t2.micro"

  # Optional: Add user data for initial setup
  user_data = <<-EOF
#!/bin/bash
apt-get update
apt-get install -y nginx
EOF

  # Optional: Attach a static IP to the instance
  aws_lightsail_static_ip "lightsail_static_ip" {
    name = "lightsail-static-ip"
  }

  # Optional: Create a domain and add a domain entry
  aws_lightsail_domain "lightsail_domain" {
    domain_name = "example.com"
  }

  aws_lightsail_domain_entry "lightsail_domain_entry" {
    domain_name = "example.com"
    name        = "www"
    target      = aws_lightsail_static_ip.lightsail_static_ip.ip_address
    type        = "A"
  }

  # Optional: Generate a key pair for SSH access
  aws_lightsail_key_pair "lightsail_key_pair" {
    name = "lightsail-key-pair"
  }

  # Optional: Open a public port for SSH access
  aws_lightsail_instance_public_port "lightsail_instance_public_port" {
    instance_name = aws_lightsail_instance.lightsail_instance.name
    port_number   = 22
    protocol      = "tcp"
  }

  # Optional: Attach the static IP to the instance
  aws_lightsail_static_ip_attachment "lightsail_static_ip_attachment" {
    instance_name = aws_lightsail_instance.lightsail_instance.name
    static_ip_name = aws_lightsail_static_ip.lightsail_static_ip.name
  }
}
