```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lightsail_instance" "lightsail_db_instance" {
  availability_zone = "us-east-1a"
  blueprint_id     = "postgres_12"
  bundle_id       = "micro_1_0"
  name            = "lightsail-db-instance"

  # Enable SSH access for RDS cluster
  public_port = 22
}

resource "aws_rds_cluster" "postgres_cluster" {
  engine              = "postgres"
  engine_version      = "12.6"
  allocated_storage   = 20
  master_username    = "admin"
  master_password    = "securepassword123"
  cluster_identifier = "lightsail-postgres-cluster"
  apply_immediately = true

  # Associate the Lightsail instance with the RDS cluster
  vpc_security_group_ids = [aws_lightsail_instance.lightsail_db_instance.security_groups[0]]

  # Configure the parameter group for immediate changes
  parameter_group_name = aws_rds_cluster_parameter_group.postgres_parameter_group.name
}

resource "aws_rds_cluster_parameter_group" "postgres_parameter_group" {
  family = "postgres12"
  name   = "lightsail-postgres-parameter-group"

  parameter {
    name         = "autocommit"
    value        = "on"
    apply_method = "immediate"
  }
}

# Optionally, create a snapshot for immediate changes
resource "aws_rds_cluster_snapshot" "postgres_snapshot" {
  cluster_identifier = aws_rds_cluster.postgres_cluster.cluster_identifier
  snapshot_identifier = "lightsail-postgres-snapshot"
}
