provider "aws" {
  region = "us-east-1"
}

resource "aws_sns_topic" "glacier_notification_topic" {
  name = "glacier-notification-topic"
}

resource "aws_s3_bucket" "glacier_vault_bucket" {
  bucket = "glacier-vault-bucket-${random_string.random_suffix.hex}"
  acl    = "private"

  tags = {
    Name        = "Glacier Vault Bucket"
    Environment = "Development"
  }
}

resource "aws_s3_bucket_notification" "glacier_vault_notification" {
  bucket = aws_s3_bucket.glacier_vault_bucket.id

  lambda_function {
    lambda_function_arn = aws_lambda_function.glacier_vault_lambda.arn
    events              = ["s3:ObjectCreated:*"]
    filter_prefix       = "glacier/"
  }

  depends_on = [aws_lambda_function.glacier_vault_lambda]
}

resource "aws_lambda_function" "glacier_vault_lambda" {
  filename      = "glacier_vault_lambda.zip"
  function_name = "glacier_vault_lambda"
  role          = aws_iam_role.glacier_vault_lambda_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  environment {
    variables = {
      GLACIER_NOTIFICATION_TOPIC_ARN = aws_sns_topic.glacier_notification_topic.arn
    }
  }

  source_code_hash = filebase64sha256("glacier_vault_lambda.zip")
}

resource "aws_iam_role" "glacier_vault_lambda_role" {
  name = "glacier-vault-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glacier_vault_lambda_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.glacier_vault_lambda_role.name
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
  upper = false
  lower = false
}
```

This Terraform program creates an S3 Glacier vault with a notification configuration that triggers when an archive retrieval completes. It includes an SNS topic for notifications, an S3 bucket to store the archives, a Lambda function to handle the notifications, and IAM roles for the Lambda function. The program uses default values for AWS identifiers where possible and includes comments for clarity.

